from langchain.tools import BaseTool, StructuredTool, tool
from langchain.pydantic_v1 import BaseModel, Field
from typing import Optional, Type

# Способ 1: Декоратор @tool (самый простой)
@tool
def search_documentation(query: str) -> str:
    """Поиск в документации. Используй когда нужно найти информацию в docs."""
    # Реальная реализация поиска
    results = vector_db.search(query, top_k=3)
    return "\n".join(results)

# Способ 2: StructuredTool (с валидацией параметров)
class SearchInput(BaseModel):
    query: str = Field(description="Поисковый запрос")
    max_results: int = Field(default=5, description="Максимум результатов")
    filter_category: Optional[str] = Field(default=None, description="Категория для фильтрации")

search_tool = StructuredTool.from_function(
    func=search_documentation,
    name="DocumentationSearch",
    description="Поиск информации в документации с фильтрами",
    args_schema=SearchInput
)

# Способ 3: Наследование от BaseTool (максимальный контроль)
class CodeAnalyzerTool(BaseTool):
    name = "CodeAnalyzer"
    description = "Анализирует код и находит потенциальные проблемы"

    def _run(self, code: str, language: str = "python") -> str:
        """Синхронное выполнение"""
        # Анализ кода
        issues = self.analyze_code(code, language)
        return self.format_results(issues)

    async def _arun(self, code: str, language: str = "python") -> str:
        """Асинхронное выполнение"""
        issues = await self.analyze_code_async(code, language)
        return self.format_results(issues)

    def analyze_code(self, code: str, language: str) -> list:
        # Статический анализ кода
        # Используем pylint, eslint и т.д.
        return []

    def format_results(self, issues: list) -> str:
        if not issues:
            return "Проблем не найдено!"
        return "\n".join(f"- {issue}" for issue in issues)

# Способ 4: Tool с состоянием
class DatabaseTool(BaseTool):
    name = "Database"
    description = "Выполнение SQL запросов к базе данных"

    # Состояние
    connection = None
    query_history = []

    def __init__(self, connection_string: str):
        super().__init__()
        self.connection = create_connection(connection_string)

    def _run(self, query: str) -> str:
        # Валидация SQL injection
        if not self.is_safe_query(query):
            return "Небезопасный запрос!"

        # Выполнение
        results = self.connection.execute(query)

        # Сохранение в историю
        self.query_history.append({
            'query': query,
            'timestamp': datetime.now(),
            'rows': len(results)
        })

        return self.format_results(results)

    def is_safe_query(self, query: str) -> bool:
        # Проверка на SQL injection
        dangerous_keywords = ['DROP', 'DELETE', 'TRUNCATE', 'ALTER']
        return not any(kw in query.upper() for kw in dangerous_keywords)

